window.RI1_UNITS = {"11":{"unit":11,"code":"RI1-U11","title":"PLASTIC PLANET","startNumber":264,"endNumber":296,"entries":[{"number":264,"term":"industry (n) · industrial (a) # industrious (a)","spoken":"industry , industrial , industrious","ipa":"industry /ˈɪndəstri/ · industrial /ˌɪˈndʌstriəl/ · industrious /ˌɪˈndʌstriəs/","type":"noun · adjective · word family","meaning":"ngành công nghiệp · thuộc công nghiệp # chăm chỉ/cần cù","definition":"Industrious, hard-working, and diligent describe a person who works carefully; industrial relates to industry or manufacturing.","note":"industrious: chăm chỉ; industrial: thuộc công nghiệp. Cùng gốc nhưng không cùng nghĩa.","example":"The industrious employee works diligently, while industrial policy concerns manufacturing and the wider industry."},{"number":265,"term":"packaging (n)","spoken":"packaging","ipa":"packaging /ˈpækɪdʒɪŋ/","type":"noun","meaning":"bao bì đóng gói","definition":"Material used to wrap, protect, store, or present a product.","note":"","example":"Manufacturers are redesigning packaging so that it uses less plastic."},{"number":266,"term":"machinery (n)","spoken":"machinery","ipa":"machinery /məˈʃiːnɚi/","type":"noun","meaning":"máy móc (nói chung)","definition":"Machines considered together, especially those used in industry.","note":"","example":"Modern recycling machinery can separate several types of plastic automatically."},{"number":267,"term":"textile (n)","spoken":"textile","ipa":"textile /ˈtɛˌkstaɪl/","type":"noun","meaning":"ngành dệt may","definition":"Cloth or fabric, or the industry that produces it.","note":"","example":"The textile industry uses plastic fibres to produce some forms of clothing."},{"number":268,"term":"consume (v) · consumer (n) · consumption (n) · consumer product","spoken":"consume , consumer , consumption , consumer product","ipa":"consume /kəˈnsuːm/ · consumer /kəˈnsuːmɚ/ · consumption /kəˈnsʌmpʃən/ · product /ˈprɑːdəkt/","type":"verb · noun · word family","meaning":"tiêu thụ/tiêu dùng · người tiêu dùng · sự/lượng tiêu thụ · hàng tiêu dùng","definition":"To use goods or services; a consumer uses them, and a consumer product is made for personal use.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Consumers often consume products without considering the environmental cost of their consumption."},{"number":269,"term":"average (a) · on average","spoken":"average , on average","ipa":"average /ˈævɚɪdʒ/","type":"adjective · phrase / pattern · word family","meaning":"trung bình · tính trung bình","definition":"Typical or calculated from a set of values; on average describes the usual result across that set.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"On average, each household uses less plastic than it did five years ago."},{"number":270,"term":"extract (v)","spoken":"extract","ipa":"extract /ɪkˈstrækt/","type":"verb","meaning":"chiết xuất từ…","definition":"To remove or obtain a substance from a material or source.","note":"","example":"Factories extract chemicals from oil before using them to make plastic."},{"number":271,"term":"straw (n)","spoken":"straw","ipa":"straw /strɔː/","type":"noun","meaning":"ống hút nước","definition":"A thin tube used for drinking; also dried stems of grain used as material.","note":"","example":"The café replaced each plastic straw with a reusable metal one."},{"number":272,"term":"waste (n) ~ litter (n) ~ rubbish/trash/garbage (n) · industrial waste · household waste","spoken":"waste , litter , rubbish or trash or garbage , industrial waste , household waste","ipa":"waste /weɪst/ · litter /ˈlɪtɚ/ · rubbish /ˈrʌbɪʃ/ · trash /træʃ/ · garbage /ˈɡɑːrbɪdʒ/ · industrial /ˌɪˈndʌstriəl/ · household /ˈhaʊˌshoʊld/","type":"noun · word family","meaning":"chất thải ~ rác bị vứt bừa bãi ~ rác sinh hoạt nói chung · chất thải công nghiệp · rác thải gia đình","definition":"Litter is small waste left in public; rubbish, trash, and garbage are general household waste; waste is the broad formal term.","note":"litter là rác bị vứt bừa bãi; rubbish (BrE), trash/garbage (AmE) là rác nói chung; waste thường dùng trong ngữ cảnh môi trường/sản xuất.","example":"Litter is waste dropped in public places; rubbish, trash, and garbage are broader everyday terms."},{"number":273,"term":"aware (a) of st · awareness (n) · raise awareness of/about st","spoken":"aware of something , awareness , raise awareness of or about something","ipa":"aware /əˈwɛr/ · awareness /əˈwɛrnəs/ · raise /reɪz/ · about /əˈbaʊt/","type":"noun · adjective · phrase / pattern · word family","meaning":"nhận thức được điều gì · sự nhận thức · nâng cao nhận thức về điều gì","definition":"Knowing about something; knowledge and understanding.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: be aware of st · awareness (n) · raise awareness about st","example":"Students should be aware of plastic waste, build awareness, and raise awareness about recycling."},{"number":274,"term":"marine (a) · marine life","spoken":"marine , marine life","ipa":"marine /mɚˈiːn/ · life /laɪf/","type":"adjective · word family","meaning":"thuộc biển · sinh vật biển","definition":"Belonging to or characteristic of the sea; existing or found in the sea; formed or produced by the sea.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Plastic waste can cause serious harm to marine life."},{"number":275,"term":"end (v) up + V-ing","spoken":"end up + doing","ipa":"end /ɛnd/ · up /ʌp/","type":"phrasal verb","meaning":"kết thúc/kết cục là…","definition":"To finally be in a particular situation or do something, often unexpectedly.","note":"Giữ đúng mẫu từ đi kèm: end (v) up + V-ing.","example":"Without better waste collection, more plastic may end up entering the ocean."},{"number":276,"term":"degrade (v) · biodegrade (v)","spoken":"degrade , biodegrade","ipa":"degrade /dɪˈɡreɪd/ · biodegrade /ˌbaɪoʊdɪˈɡreɪd/","type":"verb · word family","meaning":"làm xuống cấp/phân hủy · phân hủy sinh học","definition":"To degrade is to become worse or break down; to biodegrade is to break down naturally through living organisms.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Ordinary plastic degrades slowly, while some plant-based materials biodegrade more quickly."},{"number":277,"term":"constant (a)","spoken":"constant","ipa":"constant /ˈkɑːnstənt/","type":"adjective","meaning":"liên tục, liên miên","definition":"Unchanged through time or space; permanent.","note":"","example":"The factory releases a constant flow of warm water into the river."},{"number":278,"term":"confuse (v) A with B · confusion (n)","spoken":"confuse A with B , confusion","ipa":"confuse /kəˈnfjuːz/ · confusion /kəˈnfjuːʒən/","type":"verb · noun · word family","meaning":"nhầm người/vật này với người/vật khác · sự nhầm lẫn/bối rối","definition":"To confuse A with B is to mistake one person or thing for another; confusion is the resulting uncertainty or mistake.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Sea animals may confuse small pieces of plastic with food, causing serious confusion."},{"number":279,"term":"release (v)","spoken":"release","ipa":"release /riˈliːs/","type":"verb","meaning":"thải ra…","definition":"To send out a gas, smell, heat, light, or other substance.","note":"emit trang trọng/khoa học hơn; give off thường dùng cho mùi, nhiệt, ánh sáng; release nhấn mạnh việc cho thoát ra.","example":"Burning plastic can release harmful chemicals into the air."},{"number":280,"term":"result in (v) ~ cause (v)","spoken":"result in , cause","ipa":"result /rɪˈzʌlt/ · cause /kɑːz/","type":"verb · word family","meaning":"dẫn đến/gây ra","definition":"To cause a particular situation or result.","note":"result in + kết quả; result from + nguyên nhân. Cause có thể đi trực tiếp với danh từ.","example":"Poor waste management can result in plastic entering the ocean."},{"number":281,"term":"long-term (a) · in the long term","spoken":"long-term , in the long term","ipa":"long-term /ˌlɔːˈŋtɝːm/ · long /lɔːŋ/ · term /tɝːm/","type":"adjective · word family","meaning":"dài hạn/lâu dài · về lâu dài","definition":"Becoming evident after a relatively long time period.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Long-term planning is needed to reduce pollution in the long term."},{"number":282,"term":"type (n) · typical (a)","spoken":"type , typical","ipa":"type /taɪp/ · typical /ˈtɪpəkəl/","type":"noun · adjective · word family","meaning":"loại/kiểu · điển hình/đặc trưng","definition":"A type is a category; typical means having the usual features of a group.","note":"a type of + danh từ; be typical of + danh từ.","example":"This type of packaging is typical of products designed for single use."},{"number":283,"term":"rough (a) >< smooth (a) · roughly (adv) ~ approximately (adv)","spoken":"rough , smooth , roughly , approximately","ipa":"rough /rʌf/ · smooth /smuːð/ · roughly /ˈrʌfli/ · approximately /əˈprɑːksəmətli/","type":"adjective · adverb · word family","meaning":"gồ ghề/thô ráp >< nhẵn/mịn · xấp xỉ","definition":"Rough means uneven; smooth means even. Roughly means approximately.","note":"rough/smooth mô tả bề mặt; roughly trước số lượng mang nghĩa xấp xỉ.","example":"The rough plastic became smoother after roughly ten minutes in the machine."},{"number":284,"term":"refund (v,n)","spoken":"refund","ipa":"refund v /rɪˈfʌnd/ · n /ˈriːfʌnd/","type":"verb · noun","meaning":"hoàn tiền","definition":"To return (money) to (someone); to reimburse.","note":"","example":"Customers can return the container and receive a small refund."},{"number":285,"term":"beverage (n) ~ drink (n) ~ soft drink (n) ~ fizzy drink (n)","spoken":"beverage , drink , soft drink , fizzy drink","ipa":"beverage /ˈbɛvərɪdʒ/ · drink /drɪŋk/ · soft drink /ˈsɔːft drɪŋk/ · fizzy drink /ˈfɪzi drɪŋk/","type":"noun · word family","meaning":"đồ uống ~ đồ uống không cồn ~ đồ uống có ga","definition":"A soft drink has no alcohol; a fizzy drink is carbonated; beverage is a general formal word for a drink.","note":"soft drink là đồ uống không cồn; fizzy drink là đồ uống có ga; beverage là từ khái quát, trang trọng hơn drink.","example":"A soft drink contains no alcohol, a fizzy drink is carbonated, and beverage is the general term."},{"number":286,"term":"container (n)","spoken":"container","ipa":"container /kəˈnteɪnɚ/","type":"noun","meaning":"hộp chứa đồ","definition":"An object used for holding, storing, or transporting something.","note":"","example":"Each container was cleaned before it was filled with drinking water."},{"number":287,"term":"consist of (v) …","spoken":"consist of …","ipa":"consist /kəˈnsɪst/","type":"verb","meaning":"bao gồm…","definition":"To be made of or formed from particular parts.","note":"consist of + thành phần; không dùng consist of from.","example":"The sample consists of several types of plastic collected from the beach."},{"number":288,"term":"tax (v,n)","spoken":"tax","ipa":"tax /tæks/","type":"verb · noun","meaning":"đánh thuế, thuế","definition":"To charge money for government purposes; money charged by government.","note":"","example":"Workers pay income tax, and the government taxes higher incomes."},{"number":289,"term":"responsible (a) for st · responsibility (n) · irresponsible (a)","spoken":"responsible for something , responsibility , irresponsible","ipa":"responsible /riˈspɑːnsəbəl/ · responsibility /riˌspɑːnsəˈbɪləti/ · irresponsible /ˌɪrəˈspɑːnsəbəl/","type":"noun · adjective · phrase / pattern · word family","meaning":"chịu trách nhiệm về điều gì · trách nhiệm · vô trách nhiệm","definition":"Having a duty for something; a duty to deal with something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: responsible (a) for st · responsibility (n)","example":"The council is responsible for road safety and accepts this responsibility."},{"number":290,"term":"campaign (n)","spoken":"campaign","ipa":"campaign /kæˈmpeɪn/","type":"noun","meaning":"chiến dịch","definition":"An organized series of actions designed to achieve a public, social, or political goal.","note":"","example":"The national campaign encouraged households to avoid single-use plastic."},{"number":291,"term":"incident (n)","spoken":"incident","ipa":"incident /ˈɪnsədənt/","type":"noun","meaning":"sự việc, vụ việc","definition":"A particular event, especially one that is unusual, unpleasant, or important.","note":"","example":"The pollution incident led the local government to review waste controls."},{"number":292,"term":"in contrast","spoken":"in contrast","ipa":"contrast /ˈkɑːntræst/","type":"phrase / pattern","meaning":"trái ngược lại…","definition":"Used to introduce a clear difference between two people, things, or situations.","note":"","example":"In contrast, reusable containers create far less waste."},{"number":293,"term":"increase (v,n) >< decrease (v,n)","spoken":"increase , decrease","ipa":"increase v /ɪnˈkriːs/ · n /ˈɪnkriːs/ >< decrease v /dɪˈkriːs/ · n /ˈdiːkriːs/","type":"verb · noun · word family","meaning":"tăng/sự tăng >< giảm/sự giảm","definition":"To increase is to become or make greater; to decrease is to become or make smaller.","note":"decrease và increase đều dùng được như động từ và danh từ; trọng âm thay đổi theo từ loại.","example":"Energy use decreased after the repair, while production increased."},{"number":294,"term":"be set to do st","spoken":"be set to do something","ipa":"set /sɛt/","type":"phrase / pattern","meaning":"có khả năng sẽ làm gì","definition":"To be expected or scheduled to do something in the near future.","note":"put/set money aside là dành dụm; set sth aside còn có thể tạm gác một vấn đề.","example":"The city is set to introduce a tax on single-use containers next year."},{"number":295,"term":"follow one’s example","spoken":"follow one’s example","ipa":"follow /ˈfɑːloʊ/ · example /ɪˈɡzæmpəl/","type":"word / phrase","meaning":"noi gương","definition":"To behave as a model for others, or to copy another person's good behaviour.","note":"","example":"The designer set an example by using recycled materials, and younger brands followed her example."},{"number":296,"term":"quit (v) + V-ing ~ stop doing st","spoken":"quit + doing , stop doing something","ipa":"quit /kwɪt/ · stop /stɑːp/","type":"verb · phrase / pattern · word family","meaning":"ngừng/bỏ làm việc gì","definition":"To stop doing an activity, usually permanently.","note":"quit/stop + V-ing; stop to V mang nghĩa dừng việc đang làm để làm việc khác.","example":"Several shops quit providing plastic bags after the new campaign began."}],"pronunciationFocus":[{"entryNumber":266,"points":[{"category":"word-stress","note":"machinery /məˈʃiːnɚi/: trọng âm chính rơi vào /ˈʃiː/"}]},{"entryNumber":268,"points":[{"category":"word-stress","note":"consume, consumer và consumption đều nhấn trọng âm chính ở âm thứ hai"}]},{"entryNumber":275,"points":[{"category":"linking","note":"end‿up: nối /d/ cuối end với /ʌ/ đầu up"}]},{"entryNumber":276,"points":[{"category":"word-stress","note":"degrade nhấn âm cuối; biodegrade giữ trọng âm chính ở phần degrade"}]},{"entryNumber":283,"points":[{"category":"common-error","note":"rough kết thúc bằng /f/; smooth kết thúc bằng /ð/"},{"category":"final-sound","note":"Giữ rõ sự khác nhau giữa /f/ cuối rough và /ð/ cuối smooth"}]},{"entryNumber":287,"points":[{"category":"linking","note":"consist‿of: nối /t/ cuối consist với nguyên âm đầu của of"},{"category":"final-sound","note":"Khi đọc riêng consist /kəˈnsɪst/, giữ đủ cụm /st/ ở cuối"}]},{"entryNumber":289,"points":[{"category":"word-stress","note":"responsible nhấn /ˈspɑːn/; responsibility chuyển trọng âm chính sang /ˈbɪl/"}]}]}};
